117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        String address = normalizeAddress(ownerFieldsDto.getAddress());
121	        List<String> missingFields = new ArrayList<>();
122	        if (isBlank(ownerFieldsDto.getFirstName())) {
123	            missingFields.add("firstName");
124	        }
125	        if (isBlank(ownerFieldsDto.getLastName())) {
126	            missingFields.add("lastName");
127	        }
128	        if (isBlank(address)) {
129	            missingFields.add("address");
130	        }
131	        if (isBlank(ownerFieldsDto.getCity())) {
132	            missingFields.add("city");
133	        }
134	        if (isBlank(ownerFieldsDto.getTelephone())) {
135	            missingFields.add("telephone");
136	        }
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingOwnerFieldsException(missingFields);
139	        }
140	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
141	        if (isTelephoneInUse(telephone)) {
142	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
143	        }
144	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
145	        if (!sharesHousehold
146	            && isHouseholdInUse(ownerFieldsDto.getLastName(), address)) {
147	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), address);
148	        }
149	        if (isCityAtCapacity(ownerFieldsDto.getCity())) {
150	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
151	        }
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        owner.setAddress(address);
155	        owner.setTelephone(telephone);
156	        LocalDate effectiveDate = owner.getRegistrationDate() != null
157	            ? owner.getRegistrationDate() : LocalDate.now();
158	        LocalDate registrationDate = toBusinessDay(effectiveDate);
159	        if (isDailyRegistrationLimitReached(registrationDate)) {
160	            throw new DailyRegistrationLimitException(registrationDate);
161	        }
162	        owner.setRegistrationDate(registrationDate);
163	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
164	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
165	        if (sharesHousehold) {
166	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
167	        }
168	        this.clinicService.saveOwner(owner);
169	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
170	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
