277	    /**
278	     * Normalizes a street address into the canonical form stored on and returned for a newly
279	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
280	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
281	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
282	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
283	     * value is what gets persisted, echoed back, and used for every address comparison (household
284	     * duplicate detection and the shared household identifier).
285	     *
286	     * @param rawAddress the address value as supplied by the client
287	     * @return the normalized address (possibly empty, never {@code null})
288	     */
289	    private static String normalizeAddress(String rawAddress) {
290	        if (rawAddress == null) {
291	            return "";
292	        }
293	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
294	        if (collapsed.isEmpty()) {
295	            return "";
296	        }
297	        String[] tokens = collapsed.split(" ");
298	        StringBuilder sb = new StringBuilder(collapsed.length());
299	        for (int i = 0; i < tokens.length; i++) {
300	            String token = tokens[i];
301	            switch (token) {
302	                case "ST" -> token = "STREET";
303	                case "RD" -> token = "ROAD";
304	                case "AVE" -> token = "AVENUE";
305	                default -> { }
306	            }
307	            if (i > 0) {
308	                sb.append(' ');
309	            }
310	            sb.append(token);
311	        }
312	        return sb.toString();
313	    }
314	
315	    /**
316	     * Builds the customer code assigned to a newly created owner. The code is formatted
317	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
318	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
319	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
320	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
321	     *
322	     * @param city the city of the owner being created
323	     * @param lastName the last name of the owner being created
324	     * @return the customer code to assign
325	     */
326	    private String nextCustomerCode(String city, String lastName) {
327	        String city3 = letterPrefix3(city);
328	        String last3 = letterPrefix3(lastName);
329	        String normalizedCity = normalizeIdentity(city);
330	        long sequence = this.clinicService.findAllOwners().stream()
331	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
332	            .count() + 1L;
333	        return String.format("%s-%s-%04d", city3, last3, sequence);
334	    }
335	
336	    /**
337	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
338	     * characters. Values with fewer than three letters yield a shorter prefix.
339	     *
340	     * @param value the source text
341	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
342	     */
343	    private static String letterPrefix3(String value) {
344	        StringBuilder prefix = new StringBuilder(3);
345	        if (value != null) {
346	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
347	                char c = value.charAt(i);
348	                if (Character.isLetter(c)) {
349	                    prefix.append(Character.toUpperCase(c));
350	                }
351	            }
352	        }
353	        return prefix.toString();
354	    }
