356	    /**
357	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
358	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
359	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
360	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
361	     *
362	     * @param rawTelephone the telephone value as supplied by the client
363	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
364	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
365	     */
366	    private static String normalizeTelephone(String rawTelephone) {
367	        if (rawTelephone == null) {
368	            throw new InvalidTelephoneException(rawTelephone);
369	        }
370	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
371	        String e164;
372	        if (cleaned.startsWith("+")) {
373	            String digits = cleaned.substring(1);
374	            if (!digits.matches("[0-9]+")) {
375	                throw new InvalidTelephoneException(rawTelephone);
376	            }
377	            e164 = "+" + digits;
378	        } else {
379	            if (!cleaned.matches("[0-9]+")) {
380	                throw new InvalidTelephoneException(rawTelephone);
381	            }
382	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
383	            e164 = "+61" + national;
384	        }
385	        int digitCount = e164.length() - 1;
386	        if (digitCount < 8 || digitCount > 15) {
387	            throw new InvalidTelephoneException(rawTelephone);
388	        }
389	        return e164;
390	    }
