392	    /**
393	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
394	     * telephones are themselves E.164, so the values are compared directly.
395	     *
396	     * @param e164Telephone the E.164 telephone of the owner being created
397	     * @return {@code true} if another owner already has the same E.164 telephone
398	     */
399	    private boolean isTelephoneInUse(String e164Telephone) {
400	        return this.clinicService.findAllOwners().stream()
401	            .map(Owner::getTelephone)
402	            .filter(existing -> existing != null)
403	            .anyMatch(e164Telephone::equals);
404	    }
