406	    /**
407	     * Determines whether any existing owner already shares a household with the owner being created,
408	     * i.e. has both the same last name and the same address. Both fields are compared
409	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
410	     *
411	     * @param lastName the last name of the owner being created
412	     * @param address the address of the owner being created
413	     * @return {@code true} if another owner already has the same last name and address
414	     */
415	    private boolean isHouseholdInUse(String lastName, String address) {
416	        String normalizedLastName = normalizeIdentity(lastName);
417	        String normalizedAddress = normalizeIdentity(address);
418	        return this.clinicService.findAllOwners().stream()
419	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
420	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
421	    }
