423	    /**
424	     * Counts how many existing owners already share the given first name and last name with the
425	     * owner being created. Both names are compared case-insensitively (after trimming and
426	     * collapsing runs of whitespace). The count reflects the state before the new owner is
427	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
428	     *
429	     * @param firstName the first name of the owner being created
430	     * @param lastName the last name of the owner being created
431	     * @return the number of existing owners sharing the same first and last name
432	     */
433	    private int namesakeCount(String firstName, String lastName) {
434	        String normalizedFirstName = normalizeIdentity(firstName);
435	        String normalizedLastName = normalizeIdentity(lastName);
436	        return (int) this.clinicService.findAllOwners().stream()
437	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
438	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
439	            .count();
440	    }
