442	    /**
443	     * The maximum number of owners permitted in a single city. Once a city already contains this
444	     * many owners it is considered full and no further owners may be created there.
445	     */
446	    private static final int CITY_CAPACITY = 50;
447	
448	    /**
449	     * Determines whether the given city has already reached its capacity, i.e. already contains
450	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
451	     * collapsing runs of whitespace to a single space and trimming.
452	     *
453	     * @param city the city of the owner being created
454	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
455	     */
456	    private boolean isCityAtCapacity(String city) {
457	        String normalizedCity = normalizeIdentity(city);
458	        long count = this.clinicService.findAllOwners().stream()
459	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
460	            .count();
461	        return count >= CITY_CAPACITY;
462	    }
