464	    /**
465	     * The maximum number of owners that may be created on any single day. Once this many owners
466	     * already carry a {@code registrationDate} of the current day, no further owners may be created
467	     * that day.
468	     */
469	    private static final int DAILY_REGISTRATION_LIMIT = 100;
470	
471	    /**
472	     * Determines whether the daily registration limit has already been reached, i.e. whether
473	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
474	     * their {@code registrationDate}.
475	     *
476	     * @param date the current day
477	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
478	     *         registered on the given date
479	     */
480	    /**
481	     * Rolls a registration date forward onto a business day. A date that already falls on a
482	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
483	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
484	     * everything derived from it (the membership number's year segment, the daily create-limit).
485	     *
486	     * @param date the effective registration date (supplied by the client or defaulted to the
487	     *             server's current date)
488	     * @return the same date if it is a weekday, otherwise the following Monday
489	     */
490	    private static LocalDate toBusinessDay(LocalDate date) {
491	        DayOfWeek dayOfWeek = date.getDayOfWeek();
492	        if (dayOfWeek == DayOfWeek.SATURDAY) {
493	            return date.plusDays(2);
494	        }
495	        if (dayOfWeek == DayOfWeek.SUNDAY) {
496	            return date.plusDays(1);
497	        }
498	        return date;
499	    }
500	
501	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
502	        long count = this.clinicService.findAllOwners().stream()
503	            .filter(existing -> date.equals(existing.getRegistrationDate()))
504	            .count();
505	        return count >= DAILY_REGISTRATION_LIMIT;
506	    }
507	
508	    /**
509	     * The number of owners that may be created on a single day before the bulk-signup warning is
510	     * raised. Once <em>more than</em> this many owners already carry the current business day as
511	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
512	     */
513	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
514	
515	    /**
516	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
517	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
518	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
519	     *
520	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
521	     *         registered on today's business day
522	     */
523	    private boolean isBulkSignupWarning() {
524	        LocalDate today = toBusinessDay(LocalDate.now());
525	        long count = this.clinicService.findAllOwners().stream()
526	            .filter(existing -> today.equals(existing.getRegistrationDate()))
527	            .count();
528	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
529	    }
