531	    /**
532	     * Assigns the owner being created to the household identified by the given last name and
533	     * address and returns the household's stable shared identifier. The identifier is derived
534	     * deterministically from the normalized last name and address, so every member of the same
535	     * household resolves to the same value regardless of creation order. Any existing member that
536	     * does not yet carry the identifier is back-filled so all household members share it.
537	     *
538	     * @param lastName the last name of the owner being created
539	     * @param address the address of the owner being created
540	     * @return the stable household identifier shared by all members of the household
541	     */
542	    private String joinHousehold(String lastName, String address) {
543	        String householdId = householdIdFor(lastName, address);
544	        String normalizedLastName = normalizeIdentity(lastName);
545	        String normalizedAddress = normalizeIdentity(address);
546	        for (Owner existing : this.clinicService.findAllOwners()) {
547	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
548	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
549	                && !householdId.equals(existing.getHouseholdId())) {
550	                existing.setHouseholdId(householdId);
551	                this.clinicService.saveOwner(existing);
552	            }
553	        }
554	        return householdId;
555	    }
556	
557	    /**
558	     * Derives the stable household identifier for a given last name and address. The value is the
559	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
560	     * address, so it is stable across calls and identical for every member of the household.
561	     *
562	     * @param lastName the last name of the household
563	     * @param address the address of the household
564	     * @return the stable household identifier
565	     */
566	    private static String householdIdFor(String lastName, String address) {
567	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
568	        try {
569	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
570	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
571	            StringBuilder sb = new StringBuilder(digest.length * 2);
572	            for (byte b : digest) {
573	                sb.append(String.format("%02x", b));
574	            }
575	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
576	        }
577	        catch (java.security.NoSuchAlgorithmException e) {
578	            throw new IllegalStateException("SHA-256 not available", e);
579	        }
580	    }
581	
582	    /**
583	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
584	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
585	     * single space, and the result is lower-cased.
586	     *
587	     * @param value the raw field value
588	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
589	     */
590	    private static String normalizeIdentity(String value) {
591	        if (value == null) {
592	            return "";
593	        }
594	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
595	    }
596	}
